package com.example.offlineai.ipc;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.media.MediaCodec;
import android.media.MediaCodecInfo;
import android.media.MediaFormat;
import android.media.MediaMuxer;
import android.os.Build;

import com.example.offlineai.LogManager;

import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.Locale;

/**
 * Encode a sequence of PNG frame files (frame_0000.png ... frame_NNNN.png)
 * generated by WAN2.1-T2V into an H.264 MP4 file using Android system APIs
 * (MediaCodec + MediaMuxer). No third-party dependencies, no native libs.
 *
 * Usage:
 *   File mp4 = VideoEncoder.encodeFramesToMp4(framesDir, outFile, 16);
 */
public final class VideoEncoder {
    private static final String TAG = "VideoEncoder";

    private static final String MIME_TYPE = "video/avc";    // H.264
    private static final int FRAME_INTERVAL = 1;            // I-frame every 1 sec
    private static final int TIMEOUT_US = 10_000;           // dequeue timeout

    private VideoEncoder() {}

    /**
     * Encode all frame_NNNN.png files inside framesDir into an H.264 MP4 at outFile.
     * @param framesDir directory containing frame_0000.png .. frame_NNNN.png
     * @param outFile   output mp4 path (parent dir must exist)
     * @param fps       output fps (typically 16 for WAN2.1)
     * @return true on success
     */
    public static boolean encodeFramesToMp4(File framesDir, File outFile, int fps) {
        if (framesDir == null || !framesDir.isDirectory()) {
            LogManager.logE(TAG, "Frames dir invalid: " + framesDir);
            return false;
        }
        if (outFile == null) {
            LogManager.logE(TAG, "Output file is null");
            return false;
        }
        if (fps <= 0) {
            LogManager.logE(TAG, "Invalid fps: " + fps);
            return false;
        }

        // Collect frame_*.png files in order
        File[] all = framesDir.listFiles((dir, name) -> name.startsWith("frame_") && name.endsWith(".png"));
        if (all == null || all.length == 0) {
            LogManager.logE(TAG, "No frame_*.png files found in " + framesDir.getAbsolutePath());
            return false;
        }
        Arrays.sort(all, (a, b) -> a.getName().compareTo(b.getName()));
        LogManager.logI(TAG, "Encoding " + all.length + " frames @ " + fps + " fps -> " + outFile.getAbsolutePath());

        // Probe first frame to know real dimensions
        BitmapFactory.Options probe = new BitmapFactory.Options();
        probe.inJustDecodeBounds = true;
        BitmapFactory.decodeFile(all[0].getAbsolutePath(), probe);
        int width = probe.outWidth;
        int height = probe.outHeight;
        if (width <= 0 || height <= 0) {
            LogManager.logE(TAG, "Failed to probe first frame size");
            return false;
        }
        // H.264 encoder usually requires width/height to be even
        if ((width & 1) != 0) width -= 1;
        if ((height & 1) != 0) height -= 1;

        // Estimate bitrate: ~4 Mbps for 480p, scale roughly with pixel count
        int bitrate = Math.max(2_000_000, (int) ((long) width * height * fps * 0.12));

        MediaFormat format = MediaFormat.createVideoFormat(MIME_TYPE, width, height);
        format.setInteger(MediaFormat.KEY_COLOR_FORMAT,
                MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);
        format.setInteger(MediaFormat.KEY_BIT_RATE, bitrate);
        format.setInteger(MediaFormat.KEY_FRAME_RATE, fps);
        format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL, FRAME_INTERVAL);

        MediaCodec encoder = null;
        MediaMuxer muxer = null;
        boolean ok = false;
        try {
            encoder = MediaCodec.createEncoderByType(MIME_TYPE);
            encoder.configure(format, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE);
            encoder.start();

            muxer = new MediaMuxer(outFile.getAbsolutePath(), MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);
            int trackIndex = -1;
            boolean muxerStarted = false;

            MediaCodec.BufferInfo bufInfo = new MediaCodec.BufferInfo();
            long frameUs = 1_000_000L / fps;

            int inputFrameIndex = 0;
            int totalFrames = all.length;
            boolean inputDone = false;

            while (true) {
                // Feed input frames
                if (!inputDone) {
                    int inIdx = encoder.dequeueInputBuffer(TIMEOUT_US);
                    if (inIdx >= 0) {
                        if (inputFrameIndex >= totalFrames) {
                            encoder.queueInputBuffer(inIdx, 0, 0,
                                    inputFrameIndex * frameUs,
                                    MediaCodec.BUFFER_FLAG_END_OF_STREAM);
                            inputDone = true;
                        } else {
                            ByteBuffer inBuf;
                            if (Build.VERSION.SDK_INT >= 21) {
                                inBuf = encoder.getInputBuffer(inIdx);
                            } else {
                                inBuf = encoder.getInputBuffers()[inIdx];
                            }
                            if (inBuf == null) {
                                LogManager.logE(TAG, "Encoder input buffer null at idx " + inIdx);
                                return false;
                            }
                            inBuf.clear();

                            // Decode PNG -> ARGB Bitmap -> NV12/YUV420 bytes
                            Bitmap bmp = BitmapFactory.decodeFile(all[inputFrameIndex].getAbsolutePath());
                            if (bmp == null) {
                                LogManager.logE(TAG, "Failed to decode " + all[inputFrameIndex].getAbsolutePath());
                                return false;
                            }
                            byte[] yuv = argbBitmapToI420(bmp, width, height);
                            bmp.recycle();

                            inBuf.put(yuv);
                            encoder.queueInputBuffer(inIdx, 0, yuv.length,
                                    inputFrameIndex * frameUs, 0);
                            inputFrameIndex++;
                        }
                    }
                }

                // Drain output
                int outIdx = encoder.dequeueOutputBuffer(bufInfo, TIMEOUT_US);
                if (outIdx == MediaCodec.INFO_TRY_AGAIN_LATER) {
                    if (inputDone) {
                        // wait more
                        continue;
                    }
                } else if (outIdx == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED) {
                    if (muxerStarted) {
                        LogManager.logE(TAG, "Output format changed twice");
                        return false;
                    }
                    MediaFormat newFmt = encoder.getOutputFormat();
                    trackIndex = muxer.addTrack(newFmt);
                    muxer.start();
                    muxerStarted = true;
                } else if (outIdx >= 0) {
                    ByteBuffer outBuf;
                    if (Build.VERSION.SDK_INT >= 21) {
                        outBuf = encoder.getOutputBuffer(outIdx);
                    } else {
                        outBuf = encoder.getOutputBuffers()[outIdx];
                    }
                    if (outBuf == null) {
                        LogManager.logE(TAG, "Encoder output buffer null at idx " + outIdx);
                        return false;
                    }
                    if ((bufInfo.flags & MediaCodec.BUFFER_FLAG_CODEC_CONFIG) != 0) {
                        bufInfo.size = 0;
                    }
                    if (bufInfo.size > 0 && muxerStarted) {
                        outBuf.position(bufInfo.offset);
                        outBuf.limit(bufInfo.offset + bufInfo.size);
                        muxer.writeSampleData(trackIndex, outBuf, bufInfo);
                    }
                    encoder.releaseOutputBuffer(outIdx, false);
                    if ((bufInfo.flags & MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0) {
                        ok = true;
                        break;
                    }
                }
            }

            String summary = String.format(Locale.US,
                    "Encoded %d frames -> %s (%dx%d @ %d fps, ~%d kbps)",
                    totalFrames, outFile.getName(), width, height, fps, bitrate / 1000);
            LogManager.logI(TAG, summary);
            return ok;

        } catch (IOException | IllegalStateException | IllegalArgumentException e) {
            LogManager.logE(TAG, "Video encoding failed: " + e.getMessage(), e);
            return false;
        } finally {
            try {
                if (encoder != null) {
                    encoder.stop();
                    encoder.release();
                }
            } catch (Exception ignore) {}
            try {
                if (muxer != null) {
                    muxer.stop();
                    muxer.release();
                }
            } catch (Exception ignore) {}
        }
    }

    /**
     * Convert an ARGB_8888 Bitmap to I420 (planar YUV 4:2:0) byte array.
     * Required because COLOR_FormatYUV420Flexible ~= I420 for most encoders.
     * If width/height are smaller than bitmap (odd-trim), we crop the bitmap
     * implicitly by skipping last column/row.
     */
    private static byte[] argbBitmapToI420(Bitmap bmp, int width, int height) {
        int[] argb = new int[width * height];
        // Use bitmap's actual size for getPixels but cap to width/height
        int srcW = Math.min(bmp.getWidth(), width);
        int srcH = Math.min(bmp.getHeight(), height);
        bmp.getPixels(argb, 0, width, 0, 0, srcW, srcH);

        int frameSize = width * height;
        int chromaSize = frameSize / 4;
        byte[] yuv = new byte[frameSize + 2 * chromaSize];

        int yIdx = 0;
        int uIdx = frameSize;
        int vIdx = frameSize + chromaSize;

        for (int j = 0; j < height; j++) {
            for (int i = 0; i < width; i++) {
                int c = argb[j * width + i];
                int r = (c >> 16) & 0xFF;
                int g = (c >> 8)  & 0xFF;
                int b =  c        & 0xFF;
                // BT.601 full-range Y'CbCr
                int y = ((66 * r + 129 * g + 25 * b + 128) >> 8) + 16;
                yuv[yIdx++] = (byte) clamp(y, 0, 255);

                if ((j & 1) == 0 && (i & 1) == 0) {
                    int u = ((-38 * r - 74 * g + 112 * b + 128) >> 8) + 128;
                    int v = ((112 * r - 94 * g - 18 * b + 128) >> 8) + 128;
                    yuv[uIdx++] = (byte) clamp(u, 0, 255);
                    yuv[vIdx++] = (byte) clamp(v, 0, 255);
                }
            }
        }
        return yuv;
    }

    private static int clamp(int v, int lo, int hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }
}
